    unsigned ordering = ((word >> 23) & 1u)
        | (((word >> 22) & 1u) << 1);
    int store = (word & UINT32_C(0x0000001f)) == UINT32_C(0x1f);
    int release = (word & UINT32_C(0x00400000)) != 0u;
    uint8_t element_size = width == 2u ? UINT8_C(4)
        : width == 3u ? UINT8_C(8) : UINT8_C(2);
    unsigned rn = (word >> 5) & 31u;
    unsigned source = (word >> 16) & 31u;

    instruction->form_id = width_form_base[width]
        + (cdisasm_arm_form_id)(store ? 5u + operation_index
            + (release ? 5u : 0u)
            : operation_index + load_order_offset[ordering]);
