            instruction->name_id = CDISASM_ARM_NAME_PACIA171615;
            break;
        case UINT32_C(0xdac18ffe):
            instruction->name_id = CDISASM_ARM_NAME_PACIB171615;
            break;
        case UINT32_C(0xdac1a3fe):
            instruction->name_id = CDISASM_ARM_NAME_PACIASPPC;
            break;
        case UINT32_C(0xdac1a7fe):
            instruction->name_id = CDISASM_ARM_NAME_PACIBSPPC;
